import{_ as a,o as e,c as i,a4 as l}from"./chunks/framework.BybBnFXO.js";const _=JSON.parse('{"title":"圆明亮式切工","description":"","frontmatter":{"title":"圆明亮式切工","cutting":"brilliant-cut"},"headers":[],"relativePath":"zh/cutting/brilliant-cut.md","filePath":"zh/cutting/brilliant-cut.md","lastUpdated":1785929908000}'),r={name:"zh/cutting/brilliant-cut.md"};function n(o,t,d,h,c,u){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="圆明亮式切工" tabindex="-1">圆明亮式切工 <a class="header-anchor" href="#圆明亮式切工" aria-label="Permalink to &quot;圆明亮式切工&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>现代最经典的钻石切工，标准 57–58 刻面，诞生于 1919 年 Marcel Tolkowsky 的比例理论。台面、冠部、腰棱、亭部比例配合 最大化内部全反射与火彩。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>标准 57 面：台面 1 + 冠部 33 + 亭部 24（+ 可选 1 底尖 = 58）。</li><li>台面直径比约 53–58%；冠角 34–35°；亭角 40.75–41.2°。</li><li>腰棱厚度适中——过薄易崩，过厚浪费重量。</li><li>全反射率 (total internal reflection) 依赖比例精确；比例失调导致&quot;漏光窗&quot;。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>切工</th><th>备注</th></tr></thead><tbody><tr><td>diamond</td><td>Round Brilliant, 57f</td><td>—</td></tr><tr><td>zircon</td><td>Round Brilliant</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">切割总览</a>。</em></p>',8)])])}const b=a(r,[["render",n]]);export{_ as __pageData,b as default};
